#!/usr/bin/env bash
# Builds PalCraft and packages dist/PalCraft-<version>.zip:
#   Prism/                         portable Prism Launcher (unmodified, GPL-3.0) with the "PalCraft" instance
#   Prism/instances/PalCraft/.minecraft/mods/            palcraft + Fabric API
#   Prism/instances/PalCraft/.minecraft/palcraft-tools/  the Palworld reader (runs on the player's PC) + type mappings
#   Prism/instances/PalCraft/.minecraft/saves/PalCraft/  a fresh world generated by Minecraft's own server
# Nothing from Palworld or Minecraft is in the zip: Prism downloads Minecraft after sign-in, and the Pals are read
# from the player's own Palworld the first time PalCraft starts.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT=$PWD
VERSION=$(sed -n 's/^version=//p' fabric/gradle.properties)
PRISM=11.1.1
FABRIC_API=fabric-api-0.161.0+26.3.jar
CACHE=${PALCRAFT_CACHE:-$ROOT/.cache}
export JAVA_HOME=/usr/lib/jvm/java-25-openjdk-amd64
mkdir -p "$CACHE"

fetch() { [ -f "$CACHE/$2" ] || curl -sSfL -o "$CACHE/$2" "$1"; }
fetch "https://github.com/PrismLauncher/PrismLauncher/releases/download/$PRISM/PrismLauncher-Windows-MSVC-Portable-$PRISM.zip" prism-$PRISM.zip
fetch "https://raw.githubusercontent.com/PrismLauncher/PrismLauncher/$PRISM/LICENSE" prism-$PRISM-LICENSE.txt
fetch "https://cdn.modrinth.com/data/P7dR8mSH/versions/bNnaTiuM/fabric-api-0.161.0%2B26.3.jar" "$FABRIC_API"
# Microsoft Visual C++ runtime for Prism (redistributable; Microsoft lets programs ship these DLLs beside them)
fetch "https://files.pythonhosted.org/packages/fe/17/7a1eace5a7c6083bd99db861625c08bb37010dfbe90ed7a0194ae0281689/msvc_runtime-14.44.35112-cp313-cp313-win_amd64.whl" msvc-runtime-14.44.35112.whl
# Unreal type mappings for Palworld, from PalDex (MIT, Catherine Renelle): describes class layouts, no game content.
fetch "https://raw.githubusercontent.com/catrenelle/PalDex/5a0f591582e91e2f9c294bcc6cb186ad87094523/extractor/Mappings.usmap" Mappings.usmap

python3 tools/gen.py
(cd fabric && ./gradlew build --no-daemon -q)
dotnet publish extractor -c Release -r win-x64 --self-contained true -p:PublishSingleFile=true \
  -p:IncludeNativeLibrariesForSelfExtract=true -p:EnableCompressionInSingleFile=true -p:DebugType=none \
  -o "$CACHE/extractor" -nologo -v q

# a fresh world from Minecraft's own server (with PalCraft loaded, so it is a PalCraft world from the start)
if [ ! -d "$CACHE/world/PalCraft" ]; then
  rm -rf fabric/run/PalCraft fabric/run/logs
  (cd fabric && ( until grep -q "Done (" run/logs/latest.log 2>/dev/null; do sleep 3; done; echo stop ) | ./gradlew runServer --no-daemon -q >/dev/null 2>&1) || true
  mkdir -p "$CACHE/world" && cp -r fabric/run/PalCraft "$CACHE/world/"
  rm -f "$CACHE/world/PalCraft/session.lock"
fi

B=$ROOT/dist/bundle
rm -rf "$ROOT/dist" && mkdir -p "$B/Prism"
unzip -q "$CACHE/prism-$PRISM.zip" -d "$B/Prism"
cp "$CACHE/prism-$PRISM-LICENSE.txt" "$B/Prism/LICENSE-PrismLauncher.txt"
for dll in msvcp140.dll msvcp140_1.dll msvcp140_2.dll vcruntime140.dll vcruntime140_1.dll; do
  unzip -q -j -o "$CACHE/msvc-runtime-14.44.35112.whl" "msvc_runtime-14.44.35112.data/data/Scripts/$dll" -d "$B/Prism"
done
cp tools/bundle/prismlauncher.cfg "$B/Prism/prismlauncher.cfg"
I=$B/Prism/instances/PalCraft
mkdir -p "$I/.minecraft/mods" "$I/.minecraft/palcraft-tools" "$I/.minecraft/saves" "$I/.minecraft/config"
cp tools/bundle/instance.cfg tools/bundle/mmc-pack.json "$I/"
cp fabric/build/libs/palcraft-$VERSION.jar "$CACHE/$FABRIC_API" "$I/.minecraft/mods/"
cp "$CACHE/extractor/PalCraftExtractor.exe" "$CACHE/Mappings.usmap" "$I/.minecraft/palcraft-tools/"
cp -r "$CACHE/world/PalCraft" "$I/.minecraft/saves/"
cp tools/bundle/THIRD-PARTY.txt "$B/THIRD-PARTY.txt"
sed -i "s/{PRISM_VERSION}/$PRISM/g; s/{VERSION}/$VERSION/g" "$B/THIRD-PARTY.txt"
cp LICENSE README.md "$B/"
(cd "$B" && zip -q -X -r "$ROOT/dist/PalCraft-$VERSION.zip" .)
ls -l "$ROOT/dist/PalCraft-$VERSION.zip"
sha256sum "$ROOT/dist/PalCraft-$VERSION.zip"
